import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    begin, end = parts[0], parts[1]
    k = int(lines[1])
    words = set(lines[2:2+k])
    if end not in words: print(0); sys.exit(0)
    from collections import deque
    q = deque([(begin, 1)])
    visited = {begin}
    ans = 0
    while q:
        curr, dist = q.popleft()
        if curr == end: ans = dist; break
        for i in range(len(curr)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nxt = curr[:i] + c + curr[i+1:]
                if nxt in words and nxt not in visited:
                    visited.add(nxt)
                    q.append((nxt, dist + 1))
    print(ans)
